css:
.loader { display: grid; grid-template-columns: repeat(2, 1fr); gap: calc(var(--loader-size) * .1); width: var(--loader-size); height: var(--loader-size); }
.loader span { border-radius: calc(var(--loader-size) * .16); background: var(--loader-color); animation: twFade calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .6); }
@keyframes twFade { 0%, 100% { opacity: 1; } 50% { opacity: .2; } }
